	clk_prepare_enable(decon->res.aclk_disp);

	if (decon->state == DECON_STATE_INIT)
		decon_clocks_info(decon);

	mutex_unlock(&decon->mutex);
	decon_dbg("decon %s -\n", __func__);

	return 0;
}

