static int drm_stub_open(struct inode *inode, struct file *filp) {
    struct drm_minor *minor;
    int err = -ENODEV;
    drm_global_mutex_lock();
    minor = idr_find(&drm_minors_idr, minor_id);
    if (!minor) goto out;
    err = drm_open(filp->f_path.dentry->d_inode, filp);
out:
    drm_global_mutex_unlock();
    return err;
}
```

So blocked on `drm_global_mutex` — some other thread holds it forever, i.e., a deadlock in our DRM driver (our decon KMS work!). Another process holding drm_global_mutex and stuck.

Find holders: check other processes' stacks for drm_global_mutex contention: search /proc/*/stack for drm_ functions.

