/* KWin always uses ADDFB2 with DRM_MODE_FB_MODIFIERS.  This 3.10 kernel
 * rejects that flag in drm_crtc.c and the DECON driver only scans out linear
 * layouts, so drop the flag and fall back to plain ADDFB2. */
int drmModeAddFB2WithModifiers(int fd, uint32_t width, uint32_t height,
                               uint32_t pixel_format, const uint32_t bo_handles[4],
                               const uint32_t pitches[4], const uint32_t offsets[4],
                               const uint64_t modifier[4], uint32_t *buf_id,
                               uint32_t flags)
{
    static int (*real_addfb2)(int, uint32_t, uint32_t, uint32_t, const uint32_t[4],
                              const uint32_t[4], const uint32_t[4], uint32_t *, uint32_t);
    if (!real_addfb2)
        real_addfb2 = dlsym(RTLD_NEXT, "drmModeAddFB2");
    if (!real_addfb2)
        return -1;
    (void)modifier;
    (void)flags;
    return real_addfb2(fd, width, height, pixel_format, bo_handles, pitches,
                       offsets, buf_id, 0);
}
EOF
