#include <QCoreApplication>
#include <QDBusConnection>
#include <QDBusMessage>
#include <QDBusUnixFileDescriptor>
#include <QVariantMap>
#include <QImage>
#include <QFile>
#include <unistd.h>
#include <cstdio>

int main(int argc, char **argv)
{
    QCoreApplication app(argc, argv);
    const int w = argc > 1 ? atoi(argv[1]) : 720;
    const int h = argc > 2 ? atoi(argv[2]) : 1280;
    const QString out = argc > 3 ? QString::fromLocal8Bit(argv[3]) : QStringLiteral("/data/shot2.png");

    QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.KWin"),
                                                      QStringLiteral("/org/kde/KWin/ScreenShot2"),
                                                      QStringLiteral("org.kde.kwin.ScreenShot2"),
                                                      QStringLiteral("CaptureArea"));
    msg << 0 << 0 << w << h << (uint)0 << QVariantMap();
    QDBusMessage reply = QDBusConnection::sessionBus().call(msg, QDBus::Block, 10000);
    if (reply.type() != QDBusMessage::ReplyMessage) {
        fprintf(stderr, "call failed: %s\n", qPrintable(reply.errorMessage()));
        return 1;
    }
    QVariant v = reply.arguments().value(0);
    QDBusUnixFileDescriptor ufd = v.value<QDBusUnixFileDescriptor>();
    int fd = ufd.fileDescriptor();
    if (fd < 0) { fprintf(stderr, "no fd\n"); return 1; }
    QImage img(w, h, QImage::Format_ARGB32);
    ssize_t total = (ssize_t)w * h * 4, got = 0;
    while (got < total) {
        ssize_t n = read(fd, img.bits() + got, total - got);
        if (n <= 0) break;
        got += n;
    }
    fprintf(stderr, "read %zd/%zd bytes\n", got, total);
    close(fd);
    if (!img.save(out)) { fprintf(stderr, "save failed\n"); return 1; }
    printf("saved %s\n", qPrintable(out));
    return 0;
}
EOF
