			/* Registers are programmed; keep the frame either way. */
			DRM_DEBUG_KMS("DECON commit: vsync never latched, frame kept\n");
			ret = 0;
		} else {
			ret = retry;
		}
	}
	if (ret)
		DRM_ERROR("DECON commit failed: %d\n", ret);

	return ret;
}

