new='''bool exynos7580_fb_is_blank(struct drm_framebuffer *fb)
{
	struct drm_gem_object *obj;
	void *map;
	u32 first = 0, cur;
	bool uniform = true, have_first = false;
	unsigned int y, x, nonuniform = 0;

	if (!fb || !fb->pitches[0] || !fb->height)
		return false;
	obj = drm_fb_cma_get_gem_obj(fb, 0);
	if (!obj || !obj->import_attach || !obj->import_attach->dmabuf)
		return false;
	if (dma_buf_begin_cpu_access(obj->import_attach->dmabuf, 0,
				     obj->size, DMA_FROM_DEVICE))
		return false;
	map = dma_buf_vmap(obj->import_attach->dmabuf);
	if (!map) {
		dma_buf_end_cpu_access(obj->import_attach->dmabuf, 0,
				       obj->size, DMA_FROM_DEVICE);
		return false;
	}
	/*
	 * A frame KWin never rendered is either all zero or one uniform clear
	 * colour (0xff000000, 0xff161616, ...).  A real scene is never uniform,
	 * so uniformity is what tells them apart - sampling cannot.
	 */
	for (y = 0; y < fb->height && uniform; y++) {
		const u32 *row = (const u32 *)((const u8 *)map + y * fb->pitches[0]);

		for (x = 0; x < fb->width; x += 4) {
			cur = row[x];
			if (!have_first) {
				first = cur;
				have_first = true;
			} else if (cur != first) {
				uniform = false;
				nonuniform = cur;
				break;
			}
		}
	}
	dma_buf_vunmap(obj->import_attach->dmabuf, map);
	dma_buf_end_cpu_access(obj->import_attach->dmabuf, 0, obj->size,
			       DMA_FROM_DEVICE);
	pr_info("exynos7580: fb %u uniform=%d first=%08x other=%08x\\n",
		fb->base.id, uniform, first, nonuniform);
	return uniform;
}
