p="/run/media/asdf/db69437b-ed35-414a-8bd1-bade16b06830/j7k/gpu31/scratch-k94/drivers/gpu/drm/exynos7580/exynos_drm7580_dmabuf.c"
s=open(p).read()
start=s.index("bool exynos7580_fb_is_blank(struct drm_framebuffer *fb)")
end=s.index("EXPORT_SYMBOL_GPL(exynos7580_fb_is_blank);")+len("EXPORT_SYMBOL_GPL(exynos7580_fb_is_blank);")
new='''bool exynos7580_fb_is_blank(struct drm_framebuffer *fb)
{
	struct drm_gem_object *obj;
	void *map;
	u32 seen[4] = { 0, 0, 0, 0 };
	unsigned int nseen = 0, y, x, i;
	bool few = true, dup;

	if (!fb || !fb->pitches[0] || !fb->height)
		return false;
	obj = drm_fb_cma_get_gem_obj(fb, 0);
	if (!obj || !obj->import_attach || !obj->import_attach->dmabuf)
		return false;
	if (dma_buf_begin_cpu_access(obj->import_attach->dmabuf, 0,
				     obj->size, DMA_FROM_DEVICE))
		return false;
	map = dma_buf_vmap(obj->import_attach->dmabuf);
	if (!map) {
		dma_buf_end_cpu_access(obj->import_attach->dmabuf, 0,
				       obj->size, DMA_FROM_DEVICE);
		return false;
	}
	/*
	 * An unrendered KWin frame is a clear colour or two (00000000 /
	 * ff000000 / ff161616), never a picture.  Stop as soon as a fourth
	 * distinct sampled value shows up: that is real content.
	 */
	for (y = 0; y < fb->height && few; y++) {
		const u32 *row = (const u32 *)((const u8 *)map + y * fb->pitches[0]);

		for (x = 0; x < fb->width; x += 4) {
			u32 cur = row[x];

			dup = false;
			for (i = 0; i < nseen; i++)
				if (seen[i] == cur) {
					dup = true;
					break;
				}
			if (dup)
				continue;
			if (nseen == 3) {	/* fourth colour: real content */
				few = false;
				break;
			}
			seen[nseen++] = cur;
		}
	}
	dma_buf_vunmap(obj->import_attach->dmabuf, map);
	dma_buf_end_cpu_access(obj->import_attach->dmabuf, 0, obj->size,
			       DMA_FROM_DEVICE);
	pr_info("exynos7580: fb %u blank=%d colours=%u %08x %08x %08x %08x\\n",
		fb->base.id, few, nseen, seen[0], seen[1], seen[2], seen[3]);
	return few;
}
EXPORT_SYMBOL_GPL(exynos7580_fb_is_blank);'''
s=s[:start]+new+s[end:]
open(p,"w").write(s); print("colour-count guard")
PY
D="/run/media/asdf/db69437b-ed35-414a-8bd1-bade16b06830/j7k/gpu31/scratch-k94/drivers/gpu/drm/exynos7580"; sed -i 's/MODULE_VERSION("int120")/MODULE_VERSION("int121")/' $D/exynos_drm7580_main.c; cd "/run/media/asdf/db69437b-ed35-414a-8bd1-bade16b06830/j7k/gpu31/scratch-k94" && make ARCH=arm64 CROSS_COMPILE=aarch64-linux-gnu- KCFLAGS="-Wno-error -Wno-missing-attributes -Wno-attributes" M=drivers/gpu/drm/exynos7580 modules -j4 2>&1 | grep -E "error" | head -3; strings drivers/gpu/drm/exynos7580/exynos-drm7580.ko | grep version=

